[
  {
    "event_id": "98e6495db1b1db0bcfb80946",
    "item": {
      "core_conclusion": "铠侠与SanDisk发布第十代332层QLC 3D闪存，以CBA键合架构带来业内最高位密度。",
      "mechanism": "CMOS与阵列分片键合并以PI-LTT省电，配合Toggle DDR6.0与SCA提速接口。",
      "result": "位密度超37 Gb/mm²（较八代约+60%），NAND接口首达4.8 Gb/s。",
      "project_relevance": "直接抬高QLC密度与接口速率天花板，但缺耐久和绝对带宽等系统数据。",
      "boundary": "尚未公布送样与量产时间，非系统基准。",
      "summary": "铠侠与SanDisk在FMS 2026发布第十代332层QLC闪存，以CBA键合将位密度推至超37 Gb/mm²，并首次把NAND接口提升到4.8 Gb/s。",
      "score": 86,
      "source_urls": [
        "https://www.sandisk.com/company/newsroom/press-releases/2026/2026-08-04-new-3d-flash-memory-technology-from-kioxia-and-sandisk-qlc-nand"
      ],
      "incremental_update": false
    }
  },
  {
    "event_id": "fa703ea4e809ab6220e3a2ce",
    "item": {
      "core_conclusion": "SK海力士在FMS 2026首次展示V10 375层4D NAND晶圆，为其首款采用晶圆键合的NAND产品。",
      "mechanism": "首次在NAND上引入晶圆键合，1Tb TLC首发2通道32层叠封装。",
      "result": "PS1101 QLC eSSD较176代性能提升约55%，2026年8月起向主要CSP送样。",
      "project_relevance": "推进NAND密度曲线并给出QLC eSSD的量产送样信号。",
      "boundary": "仅为展位展示，无绝对带宽与耐久数据。",
      "summary": "SK海力士在FMS 2026展示V10 375层4D NAND，首次对NAND应用晶圆键合，并计划2026年8月起向主要CSP送样PS1101 QLC eSSD。",
      "score": 77,
      "source_urls": [
        "https://news.skhynix.com/en/fms-2026/"
      ],
      "incremental_update": false
    }
  },
  {
    "event_id": "0b211e94e1801cec3f1c6ed5",
    "item": {
      "core_conclusion": "SK海力士与SanDisk在FMS 2026通过OCP发布首个开放高带宽闪存（HBF）标准规范。",
      "mechanism": "标准定义NAND堆叠高带宽层，以UCIe互联并规范接口、可靠性与封装准则。",
      "result": "容量最高512GB（基于8/16层叠），带宽分三档约0.4到3.0TB/s。",
      "project_relevance": "在HBM与SSD间建立可互操作的HBF存储层，直接重塑AI存储层级边界。",
      "boundary": "仅为规范发布，尚无硅片实测、耐久或量产时间。",
      "summary": "SK海力士与SanDisk在FMS 2026通过OCP发布首个开放HBF标准，定义最高512GB容量与0.4到3.0TB/s带宽分级，并以UCIe连接处理器。",
      "score": 91,
      "source_urls": [
        "https://news.skhynix.com/en/hbf-at-fms-2026/"
      ],
      "incremental_update": false
    }
  }
]

